def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for i in range(1, h - 1):
        if all(v == grid[i][0] for v in grid[i]) and i == h - i - 1:
            split = ("h", i)
            break
    if split is None:
        for j in range(1, w - 1):
            if all(row[j] == grid[0][j] for row in grid) and j == w - j - 1:
                split = ("v", j)
                break
    if split is None:
        raise ValueError("No centered uniform separator found")
    axis, cut = split
    if axis == "h":
        a, b = grid[:cut], grid[cut + 1:]
    else:
        a = [row[:cut] for row in grid]
        b = [row[cut + 1:] for row in grid]
    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    if len(common) != 1:
        raise ValueError(f"Expected one shared color, got {common}")
    bg = next(iter(common))
    return [[3 if x == bg and y == bg else bg for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
